import hmac
import hashlib
import struct
import time
import os
import json
from typing import Optional, Tuple

# Token format: [version:1][timestamp:8][payload_len:2][payload:N][signature:32]
# All multi-byte integers are big-endian unsigned

SECRET_KEY = os.environ.get('TOKEN_SECRET')
if not SECRET_KEY:
    raise RuntimeError(
        "TOKEN_SECRET environment variable must be set to a strong, random secret. "
        "No insecure default is provided."
    )
MAX_TOKEN_AGE = 3600  # 1 hour
MAX_PAYLOAD_SIZE = 4096

class TokenError(Exception):
    pass

class AuthToken:
    VERSION = 1
    HEADER_SIZE = 11  # 1 + 8 + 2
    SIGNATURE_SIZE = 32

    def __init__(self, secret: str):
        if not secret:
            raise ValueError("A non-empty secret is required")
        self._secret = secret.encode('utf-8') if isinstance(secret, str) else secret

    def _compute_signature(self, data: bytes) -> bytes:
        """Compute HMAC-SHA256 signature over the header+payload."""
        return hmac.new(self._secret, data, hashlib.sha256).digest()

    def generate(self, payload: dict, timestamp: Optional[int] = None) -> bytes:
        """Generate a signed token with the given payload."""
        ts = timestamp or int(time.time())
        payload_bytes = json.dumps(payload, separators=(',', ':')).encode('utf-8')

        if len(payload_bytes) > MAX_PAYLOAD_SIZE:
            raise TokenError("Payload too large")

        header = struct.pack('>BqH', self.VERSION, ts, len(payload_bytes))
        body = header + payload_bytes
        signature = self._compute_signature(body)

        return body + signature

    def _extract_fields(self, token: bytes) -> Tuple[int, int, int, bytes, bytes]:
        """Extract and parse token fields.

        Returns: (version, timestamp, payload_len, payload, signature)
        """
        if len(token) < self.HEADER_SIZE + self.SIGNATURE_SIZE:
            raise TokenError("Token too short")

        version, timestamp, payload_len = struct.unpack('>BqH', token[:self.HEADER_SIZE])

        # Validate payload_len against actual token size
        if payload_len > MAX_PAYLOAD_SIZE:
            raise TokenError("Payload length exceeds maximum")

        # Calculate expected total size
        expected_size = self.HEADER_SIZE + payload_len + self.SIGNATURE_SIZE

        if len(token) != expected_size:
            raise TokenError("Token size mismatch")

        payload = token[self.HEADER_SIZE:self.HEADER_SIZE + payload_len]
        signature = token[self.HEADER_SIZE + payload_len:]

        return version, timestamp, payload_len, payload, signature

    def _validate_timestamp(self, timestamp: int) -> bool:
        """Check if the token timestamp is within acceptable range."""
        now = int(time.time())
        age = now - timestamp
        return 0 <= age <= MAX_TOKEN_AGE

    def _verify_signature(self, token: bytes) -> bool:
        """Verify the HMAC signature of the token.

        The signature covers everything except the last 32 bytes.
        """
        if len(token) <= self.SIGNATURE_SIZE:
            return False

        signed_content = token[:-self.SIGNATURE_SIZE]
        provided_sig = token[-self.SIGNATURE_SIZE:]

        expected_sig = self._compute_signature(signed_content)
        return hmac.compare_digest(provided_sig, expected_sig)

    def verify(self, token: bytes) -> dict:
        """Verify token and return payload if valid."""
        # Verify signature FIRST before trusting any parsed fields
        if not self._verify_signature(token):
            raise TokenError("Invalid signature")

        version, timestamp, payload_len, payload, signature = self._extract_fields(token)

        if version != self.VERSION:
            raise TokenError("Unsupported token version")

        if not self._validate_timestamp(timestamp):
            raise TokenError("Token expired")

        try:
            return json.loads(payload.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            raise TokenError(f"Invalid payload: {e}")


class PermissionEngine:
    """Role-based permission checking with token-based auth."""

    ROLE_HIERARCHY = {
        'admin': 100,
        'manager': 75,
        'user': 50,
        'guest': 25
    }

    RESOURCE_PERMISSIONS = {
        'users.list': 50,
        'users.create': 75,
        'users.delete': 100,
        'reports.view': 50,
        'reports.export': 75,
        'system.config': 100,
        'system.shutdown': 100
    }

    def __init__(self, token_service: AuthToken):
        self._token_service = token_service
        self._revocation_list = set()

    def revoke_token(self, token_id: str):
        self._revocation_list.add(token_id)

    def check_access(self, token: bytes, resource: str) -> bool:
        """Check if the token grants access to the specified resource."""
        try:
            payload = self._token_service.verify(token)
        except TokenError:
            return False

        token_id = payload.get('jti', '')
        if token_id in self._revocation_list:
            return False

        role = payload.get('role', 'guest')
        user_level = self.ROLE_HIERARCHY.get(role, 0)
        required_level = self.RESOURCE_PERMISSIONS.get(resource, 100)

        return user_level >= required_level


class TokenRefreshService:
    """Handles token refresh with sliding window."""

    REFRESH_WINDOW = 300  # 5 minutes before expiry

    def __init__(self, token_service: AuthToken):
        self._token_service = token_service
        self._refresh_count = {}
        self._max_refreshes = 5

    def can_refresh(self, token: bytes) -> bool:
        """Check if token is eligible for refresh."""
        try:
            payload = self._token_service.verify(token)
            token_id = payload.get('jti', '')
            count = self._refresh_count.get(token_id, 0)
            return count < self._max_refreshes
        except TokenError:
            return False

    def refresh(self, token: bytes) -> Optional[bytes]:
        """Issue a new token if the current one is valid and within refresh window."""
        try:
            payload = self._token_service.verify(token)
        except TokenError:
            return None

        token_id = payload.get('jti', '')
        count = self._refresh_count.get(token_id, 0)

        if count >= self._max_refreshes:
            return None

        # Issue new token with same claims but fresh timestamp
        new_payload = {k: v for k, v in payload.items() if k != 'iat'}
        new_payload['iat'] = int(time.time())
        new_payload['refresh_count'] = count + 1

        self._refresh_count[token_id] = count + 1

        return self._token_service.generate(new_payload)


# Convenience function for middleware integration
def create_auth_middleware(secret: str):
    token_svc = AuthToken(secret)
    perm_engine = PermissionEngine(token_svc)
    refresh_svc = TokenRefreshService(token_svc)

    return {
        'token_service': token_svc,
        'permission_engine': perm_engine,
        'refresh_service': refresh_svc
    }
